initScript:
state.roulette = state.roulette || { bets: [], lastNumber: null };
const reds = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];
window.rouletteUpdateBetOptions = function() {
  const type = document.getElementById('roulette-bet-type').value;
  document.getElementById('roulette-number-wrap').style.display = type === 'straight' ? 'block' : 'none';
};
window.rouletteRenderBets = function() {
  const r = state.roulette;
  const list = document.getElementById('roulette-bets');
  const total = r.bets.reduce((sum, b) => sum + b.stake, 0);
  document.getElementById('roulette-total').textContent = total.toLocaleString();
  if (!r.bets.length) {
    list.innerHTML = '<p class="text-slate-500">No bets added yet.</p>';
    return;
  }
  list.innerHTML = r.bets.map((b, i) => '<div class="flex items-center justify-between gap-3 rounded-lg bg-slate-900 px-3 py-2"><span>' + (i+1) + '. ' + b.label + '</span><span class="font-bold text-amber-300">' + b.stake.toLocaleString() + ' pts</span></div>').join('');
};
window.rouletteUpdateBetOptions();
window.rouletteRenderBets();

actionHandlers.addBet:
const r = state.roulette || (state.roulette = { bets: [], lastNumber: null });
const type = document.getElementById('roulette-bet-type').value;
const stake = Math.floor(Number(document.getElementById('roulette-stake').value));
const number = Math.floor(Number(document.getElementById('roulette-number').value));
const names = {straight:'Single number ' + number, red:'Red', black:'Black', odd:'Odd', even:'Even', low:'1–18', high:'19–36', dozen1:'1st dozen (1–12)', dozen2:'2nd dozen (13–24)', dozen3:'3rd dozen (25–36)', column1:'1st column', column2:'2nd column', column3:'3rd column'};
const message = document.getElementById('roulette-message');
if (!Number.isFinite(stake) || stake < 10) { message.textContent = 'Minimum bet is 10 points.'; return; }
if (type === 'straight' && (!Number.isInteger(number) || number < 0 || number > 36)) { message.textContent = 'Choose a number from 0 to 36.'; return; }
if (stake > state.points) { message.textContent = 'Not enough points for that bet.'; return; }
state.points -= stake;
r.bets.push({ type: type, number: number, stake: stake, label: names[type] });
updatePointsDisplay();
window.rouletteRenderBets();
message.textContent = 'Bet added. You can add more bets or spin the wheel.';

actionHandlers.clearBets:
const r = state.roulette || (state.roulette = { bets: [], lastNumber: null });
const refund = r.bets.reduce((sum, b) => sum + b.stake, 0);
state.points += refund;
r.bets = [];
updatePointsDisplay();
window.rouletteRenderBets();
document.getElementById('roulette-message').textContent = refund ? 'Betting slip cleared; ' + refund.toLocaleString() + ' points refunded.' : 'Your betting slip is already empty.';

actionHandlers.spin:
const r = state.roulette || (state.roulette = { bets: [], lastNumber: null });
const msg = document.getElementById('roulette-message');
const last = document.getElementById('roulette-last-round');
if (!r.bets.length) { msg.textContent = 'Add at least one bet before spinning.'; return; }
const reds = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];
const n = Math.floor(Math.random() * 37);
const color = n === 0 ? 'green' : (reds.includes(n) ? 'red' : 'black');
let returned = 0;
const wins = [];
for (const b of r.bets) {
  let won = false, profitMultiplier = 0;
  switch (b.type) {
    case 'straight': won = n === b.number; profitMultiplier = 35; break;
    case 'red': won = color === 'red'; profitMultiplier = 1; break;
    case 'black': won = color === 'black'; profitMultiplier = 1; break;
    case 'odd': won = n !== 0 && n % 2 === 1; profitMultiplier = 1; break;
    case 'even': won = n !== 0 && n % 2 === 0; profitMultiplier = 1; break;
    case 'low': won = n >= 1 && n <= 18; profitMultiplier = 1; break;
    case 'high': won = n >= 19 && n <= 36; profitMultiplier = 1; break;
    case 'dozen1': won = n >= 1 && n <= 12; profitMultiplier = 2; break;
    case 'dozen2': won = n >= 13 && n <= 24; profitMultiplier = 2; break;
    case 'dozen3': won = n >= 25 && n <= 36; profitMultiplier = 2; break;
    case 'column1': won = n !== 0 && n % 3 === 1; profitMultiplier = 2; break;
    case 'column2': won = n !== 0 && n % 3 === 2; profitMultiplier = 2; break;
    case 'column3': won = n !== 0 && n % 3 === 0; profitMultiplier = 2; break;
  }
  if (won) {
    const payout = b.stake * (profitMultiplier + 1);
    returned += payout;
    wins.push(b.label + ' +' + (payout - b.stake).toLocaleString() + ' profit');
  }
}
state.points += returned;
r.lastNumber = n;
const wheel = document.getElementById('roulette-wheel');
wheel.className = 'mx-auto w-28 h-28 rounded-full border-8 border-amber-500 flex items-center justify-center shadow-lg shadow-black/30 ' + (color === 'red' ? 'bg-red-700' : color === 'black' ? 'bg-slate-950' : 'bg-emerald-700');
document.getElementById('roulette-result').textContent = n;
msg.textContent = 'The ball landed on ' + n + ' (' + color + '). ' + (wins.length ? wins.length + ' winning bet(s)!' : 'No winning bets this round.');
last.classList.remove('hidden');
last.innerHTML = '<div class="font-bold text-amber-300 mb-1">Round results</div><div>Result: <strong>' + n + ' (' + color + ')</strong></div><div>Returned from winning bets: <strong>' + returned.toLocaleString() + ' pts</strong></div><div>' + (wins.length ? wins.map(w => '✓ ' + w).join('<br>') : 'No winning bets.') + '</div><div class="mt-2 text-slate-400">Your bets were settled. Add new bets for the next spin.</div>';
r.bets = [];
updatePointsDisplay();
window.rouletteRenderBets();
